'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import Navbar from '@/components/landing/Navbar';
import Footer from '@/components/landing/Footer';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import styles from './menus.module.css';

interface Category {
    id: number;
    name: string;
    icon: string;
    sortOrder: number;
}

interface Menu {
    id: number;
    korName: string;
    engName: string;
    description: string;
    price: number;
    categoryName: string;
    imagesSrc: string;
}

const PsyduckIcon = () => (
    <svg width="48" height="48" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" style={{ filter: 'drop-shadow(0px 4px 6px rgba(0,0,0,0.1))' }}>
        {/* 하단 몸통 약간 */}
        <path d="M20 95 Q50 70 80 95 Z" fill="#FDE047" stroke="#D97706" strokeWidth="5" strokeLinejoin="round" />

        {/* 머리 */}
        <circle cx="50" cy="50" r="40" fill="#FDE047" stroke="#D97706" strokeWidth="5" />

        {/* 머리 위 세 가닥 털 */}
        <path d="M42 12 Q38 2 32 8" stroke="#D97706" strokeWidth="5" strokeLinecap="round" fill="none" />
        <path d="M50 10 Q50 0 50 2" stroke="#D97706" strokeWidth="5" strokeLinecap="round" fill="none" />
        <path d="M58 12 Q62 2 68 8" stroke="#D97706" strokeWidth="5" strokeLinecap="round" fill="none" />

        {/* 눈동자 */}
        <circle cx="34" cy="40" r="4" fill="#1F2937" />
        <circle cx="66" cy="40" r="4" fill="#1F2937" />

        {/* 볼터치 */}
        <ellipse cx="22" cy="52" rx="7" ry="4" fill="#FCA5A5" opacity="0.8" />
        <ellipse cx="78" cy="52" rx="7" ry="4" fill="#FCA5A5" opacity="0.8" />

        {/* 오리 주둥이 (크림색) */}
        <path d="M24 60 Q50 48 76 60 Q82 82 50 82 Q18 82 24 60 Z" fill="#FEF9C3" stroke="#D97706" strokeWidth="5" strokeLinejoin="round" />

        {/* 콧구멍 */}
        <circle cx="44" cy="60" r="1.5" fill="#D97706" />
        <circle cx="56" cy="60" r="1.5" fill="#D97706" />
    </svg>
);

const ITEMS_PER_PAGE = 6;

export default function MenusPage() {
    const [menus, setMenus] = useState<Menu[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [selectedCategory, setSelectedCategory] = useState<number | null>(null);
    const [currentPage, setCurrentPage] = useState(1);
    const [loading, setLoading] = useState(true);

    // 카테고리 로딩
    useEffect(() => {
        const fetchCategories = async () => {
            try {
                const res = await fetch('/api/categories');
                if (res.ok) {
                    const data = await res.json();
                    setCategories(data || []);
                }
            } catch (error) {
                console.error("Failed to fetch categories:", error);
            }
        };
        fetchCategories();
    }, []);

    // 메뉴 로딩 (카테고리가 바뀔 때마다 다시 로딩)
    useEffect(() => {
        const fetchMenus = async () => {
            setLoading(true);
            try {
                let url = '/api/menus';
                if (selectedCategory !== null) {
                    url += `?categoryId=${selectedCategory}`;
                }
                const res = await fetch(url);
                if (res.ok) {
                    const data = await res.json();
                    setMenus(data.menus || []);
                }
            } catch (error) {
                console.error("Failed to fetch menus:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchMenus();
        setCurrentPage(1); // 카테고리가 바뀌면 1페이지로 돌아감
    }, [selectedCategory]);

    const formatPrice = (price?: number) => {
        if (price === undefined || price === null) return '';
        return price.toLocaleString('ko-KR') + '원';
    };

    // 페이지네이션 로직
    const totalPages = Math.max(1, Math.ceil(menus.length / ITEMS_PER_PAGE));
    const paginatedMenus = menus.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

    return (
        <main className={styles.main}>
            <Navbar />

            <div className={styles.content}>
                <h1 className={styles.heading} style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '12px' }}>
                    <PsyduckIcon />
                    우리의 특별 메뉴
                </h1>

                {/* 카테고리 탭 */}
                <div className={styles.tabs}>
                    <button
                        className={`${styles.tab} ${selectedCategory === null ? styles.tabActive : ''}`}
                        onClick={() => setSelectedCategory(null)}
                    >
                        전체 보기
                    </button>
                    {categories.map(cat => (
                        <button
                            key={cat.id}
                            className={`${styles.tab} ${selectedCategory === cat.id ? styles.tabActive : ''}`}
                            onClick={() => setSelectedCategory(cat.id)}
                        >
                            {cat.icon} {cat.name}
                        </button>
                    ))}
                </div>

                {loading ? (
                    <div className={styles.emptyState}>메뉴를 불러오는 중입니다... ☕</div>
                ) : (
                    <>
                        <div className={styles.grid}>
                            {paginatedMenus.length > 0 ? (
                                paginatedMenus.map((menu) => (
                                    <Link href={`/menus/${menu.id}`} key={menu.id} style={{ textDecoration: 'none' }}>
                                        <div className={styles.card}>
                                            <img
                                                src={`/images/${menu.imagesSrc || 'blank.png'}`}
                                                alt={menu.korName}
                                                className={styles.cardImage}
                                                onError={(e) => {
                                                    (e.target as HTMLImageElement).src = '/images/blank.png';
                                                }}
                                            />
                                            <h3 className={styles.cardTitle}>{menu.korName}</h3>
                                            {menu.engName && (
                                                <div style={{ fontSize: '0.8rem', color: '#92400e', marginBottom: '8px' }}>
                                                    {menu.engName}
                                                </div>
                                            )}
                                            <p className={styles.cardDesc}>
                                                {menu.description || '맛있는 고라파덕 카페의 메뉴입니다!'}
                                            </p>
                                            <div className={styles.cardPriceContainer}>
                                                <span className={styles.cardPrice}>
                                                    {formatPrice(menu.price)}
                                                </span>
                                            </div>
                                        </div>
                                    </Link>
                                ))
                            ) : (
                                <div className={styles.emptyState}>해당 카테고리에 준비된 메뉴가 없습니다 😢</div>
                            )}
                        </div>

                        {/* Pagination UI */}
                        {menus.length > ITEMS_PER_PAGE && (
                            <div className={styles.pagination}>
                                <button
                                    className={styles.pageBtn}
                                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                    disabled={currentPage === 1}
                                    aria-label="Previous page"
                                >
                                    <ChevronLeft size={20} />
                                </button>

                                {Array.from({ length: totalPages }).map((_, i) => (
                                    <button
                                        key={i}
                                        className={`${styles.pageBtn} ${currentPage === i + 1 ? styles.pageBtnActive : ''}`}
                                        onClick={() => setCurrentPage(i + 1)}
                                    >
                                        {i + 1}
                                    </button>
                                ))}

                                <button
                                    className={styles.pageBtn}
                                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                    disabled={currentPage === totalPages}
                                    aria-label="Next page"
                                >
                                    <ChevronRight size={20} />
                                </button>
                            </div>
                        )}
                    </>
                )}
            </div>

            <Footer />
        </main>
    );
}
